typedef float rational_t;
typedef float vm_num_t;
typedef unsigned long long big_int;

class stringx;
class string_buf
{
  friend class stringx;
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
  big_int* data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
protected:
  char* chars;
  string_buf* my_buf;
  void make_room(int len);
public:
  stringx();
  stringx(const stringx& cp);
  ~stringx();
  void append(const char* str, int len = -1);
  void append(const stringx& cp);
};

extern "C" unsigned int strlen(const char*);

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const char* lhs, const stringx& rhs)
{
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

void error(const stringx& str);

class script_object
{
public:
  class instance
  {
  protected:
    stringx name;
  public:
    const stringx& get_name() const { return name; }
  };
};

class vm_executable
{
protected:
  script_object* owner;
  stringx name;
  stringx fullname;
public:
  const stringx& get_fullname() const { return fullname; }
};

class vm_thread
{
protected:
  script_object::instance* inst;
  const vm_executable* ex;
public:
  script_object::instance* get_instance() const { return inst; }
  const vm_executable* get_executable() const { return ex; }
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
protected:
  void move_SP(int n) { SP += n; }
public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { move_SP(-n); }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  protected:
    char* name;
    virtual ~function();
  public:
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class vector3d
{
public:
  rational_t x, y, z;
};
typedef vector3d vm_vector3d_t;
class trigger;

template <class T>
class singleton_ptr
{
  T* p;
public:
  operator T*() const { return p; }
};

class trigger_manager
{
  static singleton_ptr<trigger_manager> instance;
public:
  static inline trigger_manager* inst() { return instance; }
  trigger* new_point_trigger(vector3d p, rational_t r);
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

class slf_create_point_trigger_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_vector3d_t p;
    vm_num_t r;
  };
  virtual bool operator()( vm_stack& stack,entry_t entry )
  {
    SLF_PARMS;
    trigger* result = trigger_manager::inst()->new_point_trigger( parms->p, parms->r );
    SLF_RETURN;
    SLF_DONE;
  }
};
